namespace Kamada.Shared.Infrastructure.Persistence;

/// <summary>
/// Hand-over between module seeders within one seeding run (one DI scope). Ids are generated by the domain,
/// so a seeder publishes what it created and later seeders build on it – e.g. orders are placed for the clients
/// and products seeded a moment earlier. A seeder whose input is missing (its upstream seeder skipped because
/// the data already existed) skips as well: the demo scenario is created only on an empty database.
/// </summary>
public sealed class DemoSeedData
{
    /// <summary>The demo data describes a company delivering in the Tricity and Szczecin: working hours and "today" are Polish local time.</summary>
    public static readonly TimeZoneInfo TimeZone = TimeZoneInfo.FindSystemTimeZoneById("Europe/Warsaw");

    /// <summary>The demo administrator; places most demo orders.</summary>
    public Guid AdminId { get; set; }

    /// <summary>The demo seller; places every third demo order, so the phone app shows them under "Moje zamówienia".</summary>
    public Guid SellerId { get; set; }

    public IReadOnlyList<Guid> CourierIds { get; set; } = [];

    public IReadOnlyList<Guid> ProductIds { get; set; } = [];

    public IReadOnlyList<DemoShippingAddress> ShippingAddresses { get; set; } = [];

    /// <summary>Placed orders, oldest first.</summary>
    public IReadOnlyList<DemoOrder> Orders { get; set; } = [];

    /// <summary>Converts a local (Polish) date and time to an instant (UTC, as PostgreSQL timestamptz requires).</summary>
    public static DateTimeOffset AtLocalTime(DateOnly date, TimeOnly time)
    {
        var local = date.ToDateTime(time);
        return new DateTimeOffset(local, TimeZone.GetUtcOffset(local)).ToUniversalTime();
    }

    public static DateOnly LocalDate(DateTimeOffset instant) => DateOnly.FromDateTime(TimeZoneInfo.ConvertTime(instant, TimeZone).DateTime);
}
